1	package posemap
2	
3	import (
4		"errors"
5		"math"
6		"os"
7		"path/filepath"
8		"testing"
9	)
10	
11	// 规格示例：某次出现只有两条转换到地图坐标后分别位于 (1,0)、(2,0) 的
12	// 观测，保存位置应为 (1.5,0)。文件只把位置改成 (8,0)，即使观测次数仍是
13	// 两次、文件长度和校验和都正确，Open 也必须按 ErrCorrupt 拒绝。
14	func TestOpenRejectsPositionContradictingObservations(t *testing.T) {
15		path := filepath.Join(t.TempDir(), "m.pose")
16		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
17		m, err := Create(path, cfg)
18		if err != nil {
19			t.Fatal(err)
20		}
21		// t=100 位姿 (1,0)，L 观测本地 (0,0) → 地图 (1,0)；
22		// t=200 位姿 (2,0)，L 观测 → 地图 (2,0)；等权平均 (1.5,0)、次数 2。
23		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
24			{Time: 100, DX: 1, Observations: []Observation{{ID: "L"}}},
25			{Time: 200, DX: 1, Observations: []Observation{{ID: "L"}}},
26		}}); err != nil {
27			t.Fatal(err)
28		}
29		if err := m.Close(); err != nil {
30			t.Fatal(err)
31		}
32		fd := readFileData(t, path)
33		occ := fd.Landmarks[0].Occurrences[0]
34		if occ.X != 1.5 || occ.Y != 0 || occ.Count != 2 {
35			t.Fatalf("test setup wrong: %+v", occ)
36		}
37		fd.Landmarks[0].Occurrences[0].X = 8
38		writeFileDataRaw(t, path, &fd)
39	
40		saved, err := os.ReadFile(path)
41		if err != nil {
42			t.Fatal(err)
43		}
44		m2, err := Open(path)
45		if !errors.Is(err, ErrCorrupt) {
46			t.Fatalf("err = %v, want ErrCorrupt", err)
47		}
48		if m2 != nil {
49			t.Fatalf("Open returned usable map: %v", m2)
50		}
51		got, err := os.ReadFile(path)
52		if err != nil {
53			t.Fatal(err)
54		}
55		if string(got) != string(saved) {
56			t.Fatal("Open modified the rejected file")
57		}
58	}
59	
60	// 合并距离不能作为保存位置偏差的容许范围：保存位置只偏离重放均值 0.1
61	// （远小于合并距离 1）仍必须拒绝，且不能自动改正后继续使用。
62	func TestOpenRejectsPositionShiftBelowMergeDistance(t *testing.T) {
63		path := filepath.Join(t.TempDir(), "m.pose")
64		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
65		m, err := Create(path, cfg)
66		if err != nil {
67			t.Fatal(err)
68		}
69		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
70			{Time: 100, DX: 1, Observations: []Observation{{ID: "L"}}},
71			{Time: 200, DX: 1, Observations: []Observation{{ID: "L"}}},
72		}}); err != nil {
73			t.Fatal(err)
74		}
75		if err := m.Close(); err != nil {
76			t.Fatal(err)
77		}
78		fd := readFileData(t, path)
79		fd.Landmarks[0].Occurrences[0].X = 1.6 // 应为 1.5，偏差 0.1 < 合并距离 1
80		writeFileDataRaw(t, path, &fd)
81	
82		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
83			t.Fatalf("err = %v, want ErrCorrupt, map=%v", err, m)
84		}
85	}
86	
87	// 各次出现分别核对：两次出现的观测不能混用。occ1 均值 (1.5,0)、occ2 位于
88	// (3,0)，把任一次出现改成两次出现观测混算的位置都必须拒绝。
89	func TestOpenRejectsPositionMixedAcrossOccurrences(t *testing.T) {
90		path := filepath.Join(t.TempDir(), "m.pose")
91		buildOccurrenceMap(t, path)
92		fd := readFileData(t, path)
93		occs := fd.Landmarks[0].Occurrences
94		// occ1: t=100 (1,0)、t=200 (2,0) 两条观测，均值 (1.5,0)；
95		// occ2: t=300 位姿 (3,0) 的一条观测，位置 (3,0)。
96		if occs[0].X != 1.5 || occs[0].Count != 2 || occs[1].X != 3 || occs[1].Count != 1 {
97			t.Fatalf("test setup wrong: %+v", occs)
98		}
99		mixed := (1.5*2 + 3) / 3 // 假设跨出现混算会得到的“均值”
100	
101		fd.Landmarks[0].Occurrences[0].X = mixed
102		writeFileDataRaw(t, path, &fd)
103		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
104			t.Fatalf("mixed position on occ1: err = %v, want ErrCorrupt, map=%v", err, m)
105		}
106	
107		fd = readFileData(t, path)
108		fd.Landmarks[0].Occurrences[0].X = 1.5
109		fd.Landmarks[0].Occurrences[1].X = mixed
110		writeFileDataRaw(t, path, &fd)
111		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
112			t.Fatalf("mixed position on occ2: err = %v, want ErrCorrupt, map=%v", err, m)
113		}
114	}
115	
116	// 已经失效的出现也属于地图历史：其位置矛盾同样阻止打开，不能因为它不再
117	// 参与区域查询就跳过。
118	func TestOpenRejectsPositionMismatchOnInvalidatedOccurrence(t *testing.T) {
119		path := filepath.Join(t.TempDir(), "m.pose")
120		buildOccurrenceMap(t, path)
121		fd := readFileData(t, path)
122		if fd.Landmarks[0].Occurrences[0].Active {
123			t.Fatal("test setup wrong: first occurrence should be invalidated")
124		}
125		fd.Landmarks[0].Occurrences[0].X = 8
126		writeFileDataRaw(t, path, &fd)
127	
128		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
129			t.Fatalf("inactive occurrence position: err = %v, want ErrCorrupt, map=%v", err, m)
130		}
131	}
132	
133	// 篡改一条来源观测（次数不变）使重放到第二条时超出合并距离：观测依据
134	// 本身在当前位姿下不再满足接纳规则，同样按损坏拒绝。
135	func TestOpenRejectsReplayedMergeConflict(t *testing.T) {
136		path := filepath.Join(t.TempDir(), "m.pose")
137		buildOccurrenceMap(t, path)
138		fd := readFileData(t, path)
139		// t=100 的第一条观测是 occ1 的建点观测（不做距离判定），把它本地
140		// X 改成 5：建点变为地图 (6,0)；t=200 的第二条观测位于 (2,0)，距
141		// 当时均值 4 > 合并距离 1，重放冲突。
142		fd.Sources[0].Observations[0].X = 5
143		writeFileDataRaw(t, path, &fd)
144	
145		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
146			t.Fatalf("replayed conflict: err = %v, want ErrCorrupt, map=%v", err, m)
147		}
148	}
149	
150	// 同帧对同一标识的多条观测按保存的输入次序逐条重放：正常文件（最终均值
151	// 由次序决定的增量合并产生）必须打开成功，位置与查询结果逐位一致。
152	func TestOpenPositionReplayHonorsSameFrameOrder(t *testing.T) {
153		path := filepath.Join(t.TempDir(), "m.pose")
154		m, err := Create(path, sameFrameConfig())
155		if err != nil {
156			t.Fatal(err)
157		}
158		if _, err := m.ImportSegment(sameFrameLGeometry(true)); err != nil {
159			t.Fatal(err)
160		}
161		// 再做一次平移校正，使保存位置来自校正后重放；打开时必须按当前轨迹
162		// 与同帧次序复现出完全相同的均值 (-0.6,0)。
163		if _, err := m.Correct(Correction{
164			ID: "c-order", Anchor: 100,
165			Target: CorrectionTarget{X: -0.5, Y: 0, Heading: 0, Variance: 0},
166		}); err != nil {
167			t.Fatal(err)
168		}
169		if err := m.Close(); err != nil {
170			t.Fatal(err)
171		}
172	
173		m2, err := Open(path)
174		if err != nil {
175			t.Fatalf("open: %v", err)
176		}
177		defer m2.Close()
178		lms, err := m2.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
179		if err != nil {
180			t.Fatal(err)
181		}
182		if len(lms) != 1 || lms[0].Count != 5 || lms[0].X != -0.6 || lms[0].Y != 0 {
183			t.Fatalf("landmark = %+v, want (-0.6,0) count 5", lms)
184		}
185	
186		// 把同帧观测次序打乱后（观测集合与次数不变），按保存的同帧次序重放
187		// 不再复现保存值：该次序下第二条观测重放即超出合并距离，按损坏拒绝。
188		fd := readFileData(t, path)
189		obs := fd.Sources[1].Observations // t=100 帧的四条 L 观测
190		if len(obs) != 4 {
191			t.Fatalf("test setup wrong: %+v", obs)
192		}
193		obs[0].X, obs[3].X = obs[3].X, obs[0].X
194		writeFileDataRaw(t, path, &fd)
195		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
196			t.Fatalf("reordered same-frame observations: err = %v, want ErrCorrupt, map=%v", err, m)
197		}
198	}
199	
200	// 正常回环校正后保存的文件可以打开：核对的是当前轨迹重放出的位置，不
201	// 要求当前路标等于旧校正记录快照，也不改写那些历史快照。
202	func TestOpenPositionAcceptedAfterCorrection(t *testing.T) {
203		path := filepath.Join(t.TempDir(), "m.pose")
204		buildCorrectedMap(t, path)
205		m, err := Open(path)
206		if err != nil {
207			t.Fatalf("open corrected map: %v", err)
208		}
209		recs, _ := m.Corrections()
210		if len(recs) != 1 {
211			t.Fatalf("records = %+v", recs)
212		}
213		if err := m.Close(); err != nil {
214			t.Fatal(err)
215		}
216	
217		// 对同一范围再做一次不同校正后重开：旧记录快照保留提交时值，位置核对
218		// 只认当前轨迹。
219		m2, err := Open(path)
220		if err != nil {
221			t.Fatal(err)
222		}
223		if _, err := m2.Correct(Correction{ID: "c2", Anchor: 100, Target: CorrectionTarget{X: -3, Y: 2, Heading: 0.5, Variance: 4}}); err != nil {
224			t.Fatal(err)
225		}
226		if err := m2.Close(); err != nil {
227			t.Fatal(err)
228		}
229		m3, err := Open(path)
230		if err != nil {
231			t.Fatalf("reopen after recorrection: %v", err)
232		}
233		defer m3.Close()
234		recs2, _ := m3.Corrections()
235		if len(recs2) != 2 || recs2[0].ID != "c1" || recs2[1].ID != "c2" {
236			t.Fatalf("records = %+v", recs2)
237		}
238	}
239	
240	// 旧地图追加有完整依据的新帧后：旧观测贡献按其原有次数与平均位置作为
241	// 固定起点参与，新观测共同决定最终位置，合法文件打开成功。
242	func TestOpenMixedLegacyPositionAccepted(t *testing.T) {
243		path := filepath.Join(t.TempDir(), "m.pose")
244		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
245		m, err := Create(path, cfg)
246		if err != nil {
247			t.Fatal(err)
248		}
249		if _, err := m.ImportSegment(Segment{ID: "old", Frames: []Frame{
250			{Time: 100, DX: 1, Observations: []Observation{{ID: "K"}}},
251			{Time: 200, DX: 1, Observations: []Observation{{ID: "K"}}},
252		}}); err != nil {
253			t.Fatal(err)
254		}
255		writeLegacyV1File(t, path, m.state)
256		m.Close()
257	
258		m2, err := Open(path)
259		if err != nil {
260			t.Fatal(err)
261		}
262		// 旧贡献 2 次均值 (1.5,0)；新观测 (2.5,0)，最终位置 1.5+1/3。
263		if _, err := m2.ImportSegment(Segment{ID: "new", Frames: []Frame{
264			{Time: 300, DX: 0.5, Observations: []Observation{{ID: "K"}}},
265		}}); err != nil {
266			t.Fatal(err)
267		}
268		if err := m2.Close(); err != nil {
269			t.Fatal(err)
270		}
271		m3, err := Open(path)
272		if err != nil {
273			t.Fatalf("reopen mixed legacy/new file: %v", err)
274		}
275		lms, _ := m3.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
276		if len(lms) != 1 || lms[0].Count != 3 {
277			t.Fatalf("landmark = %+v, want K count 3", lms)
278		}
279		approxEq(t, "mixed legacy position", lms[0].X, 1.5+1.0/3.0)
280		m3.Close()
281	
282		// 最终位置被篡改：旧贡献起点不变、来源观测不变，仍必须拒绝。
283		fd := readFileData(t, path)
284		fd.Landmarks[0].Occurrences[0].X = 8
285		writeFileDataRaw(t, path, &fd)
286		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
287			t.Fatalf("tampered mixed position: err = %v, want ErrCorrupt, map=%v", err, m)
288		}
289	
290		// 旧贡献均值被篡改（不能当成零、也不能按缺少依据的帧数代替）：拒绝。
291		fd = readFileData(t, path)
292		fd.Landmarks[0].Occurrences[0].LegacyMX = 0
293		writeFileDataRaw(t, path, &fd)
294		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
295			t.Fatalf("tampered legacy mean: err = %v, want ErrCorrupt, map=%v", err, m)
296		}
297	}
298	
299	// 完全没有逐帧观测依据的纯旧文件不核对位置：篡改保存位置后仍按现有规则
300	// 打开，不要求补造观测。
301	func TestOpenPureLegacyFileSkipsPositionCheck(t *testing.T) {
302		path := filepath.Join(t.TempDir(), "m.pose")
303		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
304		m, err := Create(path, cfg)
305		if err != nil {
306			t.Fatal(err)
307		}
308		if _, err := m.ImportSegment(Segment{ID: "old", Frames: []Frame{
309			{Time: 100, DX: 1, Observations: []Observation{{ID: "K"}}},
310			{Time: 200, DX: 1, Observations: []Observation{{ID: "K"}}},
311		}}); err != nil {
312			t.Fatal(err)
313		}
314		writeLegacyV1File(t, path, m.state)
315		m.Close()
316	
317		fd := readFileData(t, path)
318		if len(fd.Sources) != 0 {
319			t.Fatalf("test setup wrong: sources = %+v", fd.Sources)
320		}
321		fd.Landmarks[0].X = 42
322		writeFileDataRaw(t, path, &fd)
323		m2, err := Open(path)
324		if err != nil {
325			t.Fatalf("pure legacy file must still open: %v", err)
326		}
327		m2.Close()
328	}
329	
330	// 现有可接受的有限大坐标不能仅因新增位置检查被误报为损坏：大坐标下增量
331	// 合并保存的位置必须能由同一序列逐位重放出来。
332	func TestOpenPositionCheckAcceptsLargeFiniteCoordinates(t *testing.T) {
333		path := filepath.Join(t.TempDir(), "map.bin")
334		m, err := Create(path, Config{
335			InitialTime: 1000, MaxInterval: 100, MergeDistance: 3e307,
336		})
337		if err != nil {
338			t.Fatal(err)
339		}
340		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
341			{Time: 1001, Observations: []Observation{{ID: "L", X: 8e307, Y: 0}}},
342			{Time: 1002, Observations: []Observation{{ID: "L", X: 8e307, Y: 0}}},
343			{Time: 1003, Observations: []Observation{{ID: "L", X: 1e308, Y: 0}}},
344		}}); err != nil {
345			t.Fatal(err)
346		}
347		if _, err := m.Correct(Correction{
348			ID: "c1", Anchor: 1001,
349			Target: CorrectionTarget{X: 1e307, Y: 0, Heading: 0, Variance: 0},
350		}); err != nil {
351			t.Fatal(err)
352		}
353		if err := m.Close(); err != nil {
354			t.Fatal(err)
355		}
356		m2, err := Open(path)
357		if err != nil {
358			t.Fatalf("reopen huge-coordinate corrected map: %v", err)
359		}
360		defer m2.Close()
361		lms, _ := m2.LandmarksInRect(Rect{MinX: -math.MaxFloat64, MinY: -math.MaxFloat64, MaxX: math.MaxFloat64, MaxY: math.MaxFloat64})
362		if len(lms) != 1 || !isFinite(lms[0].X) {
363			t.Fatalf("landmark = %+v", lms)
364		}
365		want := 9e307 + (1.1e308-9e307)/3
366		if math.Abs(lms[0].X-want) > math.Abs(want)*1e-12 {
367			t.Fatalf("X = %v, want ~%v", lms[0].X, want)
368		}
369	}
